import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.6vsupRmR.js";const h=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{"title":"CLI reference"},"headers":[],"relativePath":"cli.md","filePath":"cli.md"}'),l={name:"cli.md"};function d(i,e,n,c,s,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>Default index cluster: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code>.</p><p>That is the default <code>--index-addrs</code> for the <code>client</code>, <code>account</code>, <code>payment</code>, <code>repair</code>, and <code>storage</code> commands (and the <code>[storage] index_addrs</code> key in <code>arkel-node.toml</code>) — point those at the index cluster you run.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><h6 id="index" tabindex="-1"><strong>Index:</strong> <a class="header-anchor" href="#index" aria-label="Permalink to &quot;**Index:**&quot;">​</a></h6><ul><li><a href="#using-arkel">Using Arkel</a></li><li><a href="#running-a-storage-node">Running a storage node</a></li><li><a href="#operating-the-network">Operating the network</a></li></ul><p>Arkel Distributed Blob Index &amp; Storage Node</p><p><strong>Usage:</strong> <code>arkel [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="subcommands" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><a href="#arkel-storage"><code>storage</code></a> — Boot up as a high-throughput raw block storage endpoint</li><li><a href="#arkel-client"><code>client</code></a> — Upload/download objects as an iroh-native client</li><li><a href="#arkel-account"><code>account</code></a> — Account &amp; quota tools</li><li><a href="#arkel-payment"><code>payment</code></a> — Payment-operator tooling (register the quota credit key; first-wins)</li><li><a href="#arkel-repair"><code>repair</code></a> — Heal objects below target k/m (standalone, idempotent; run by cron)</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--data-dir &lt;DATA_DIR&gt;</code> — Dedicated data directory for this specific node&#39;s cryptographic identities and storage state</li><li><code>--config &lt;CONFIG&gt;</code> — Node config file (arkel-node.toml); command-line flags override it</li></ul><h2 id="using-arkel" tabindex="-1">Using Arkel <a class="header-anchor" href="#using-arkel" aria-label="Permalink to &quot;Using Arkel&quot;">​</a></h2><h3 id="arkel-client" tabindex="-1"><code>arkel client</code> <a class="header-anchor" href="#arkel-client" aria-label="Permalink to &quot;`arkel client`&quot;">​</a></h3><p>Upload/download objects as an iroh-native client</p><p><strong>Usage:</strong> <code>arkel client &lt;COMMAND&gt;</code></p><h6 id="subcommands-1" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-1" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>put</code> — Upload a file (EC + encrypt locally, shards to storage nodes, manifest via Raft)</li><li><code>get</code> — Download an object and write it to a file (or stdout)</li><li><code>rm</code> — Delete an object (removes its manifest via Raft; shards freed by GC)</li></ul><h3 id="arkel-client-put" tabindex="-1"><code>arkel client put</code> <a class="header-anchor" href="#arkel-client-put" aria-label="Permalink to &quot;`arkel client put`&quot;">​</a></h3><p>Upload a file (EC + encrypt locally, shards to storage nodes, manifest via Raft)</p><p><strong>Usage:</strong> <code>arkel client put [OPTIONS] &lt;FILE&gt;</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;FILE&gt;</code> — Path to the file to upload</li></ul><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--bucket &lt;BUCKET&gt;</code></p><p>Default value: <code>default</code></p></li><li><p><code>--key &lt;KEY&gt;</code> — Object key; defaults to the file name</p></li><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li><li><p><code>--storage-addrs &lt;STORAGE_ADDRS&gt;</code> — Storage nodes to distribute shards to, as pubkey@ip:port (comma-separated)</p></li></ul><h3 id="arkel-client-get" tabindex="-1"><code>arkel client get</code> <a class="header-anchor" href="#arkel-client-get" aria-label="Permalink to &quot;`arkel client get`&quot;">​</a></h3><p>Download an object and write it to a file (or stdout)</p><p><strong>Usage:</strong> <code>arkel client get [OPTIONS] &lt;BUCKET&gt; &lt;KEY&gt;</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;BUCKET&gt;</code></li><li><code>&lt;KEY&gt;</code></li></ul><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li><li><p><code>--storage-addrs &lt;STORAGE_ADDRS&gt;</code> — Storage nodes that may hold shards, as pubkey@ip:port (comma-separated)</p></li><li><p><code>--output &lt;OUTPUT&gt;</code></p></li></ul><h3 id="arkel-client-rm" tabindex="-1"><code>arkel client rm</code> <a class="header-anchor" href="#arkel-client-rm" aria-label="Permalink to &quot;`arkel client rm`&quot;">​</a></h3><p>Delete an object (removes its manifest via Raft; shards freed by GC)</p><p><strong>Usage:</strong> <code>arkel client rm [OPTIONS] &lt;BUCKET&gt; &lt;KEY&gt;</code></p><h6 id="arguments-2" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-2" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;BUCKET&gt;</code></li><li><code>&lt;KEY&gt;</code></li></ul><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li></ul><h3 id="arkel-account" tabindex="-1"><code>arkel account</code> <a class="header-anchor" href="#arkel-account" aria-label="Permalink to &quot;`arkel account`&quot;">​</a></h3><p>Account &amp; quota tools</p><p><strong>Usage:</strong> <code>arkel account &lt;COMMAND&gt;</code></p><h6 id="subcommands-2" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-2" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>quota</code> — Show quota and usage for an account (default: this identity)</li></ul><h3 id="arkel-account-quota" tabindex="-1"><code>arkel account quota</code> <a class="header-anchor" href="#arkel-account-quota" aria-label="Permalink to &quot;`arkel account quota`&quot;">​</a></h3><p>Show quota and usage for an account (default: this identity)</p><p><strong>Usage:</strong> <code>arkel account quota [OPTIONS]</code></p><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--account &lt;ACCOUNT&gt;</code> — Account (hex iroh pubkey); defaults to this node&#39;s identity</p></li><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li></ul><h2 id="running-a-storage-node" tabindex="-1">Running a storage node <a class="header-anchor" href="#running-a-storage-node" aria-label="Permalink to &quot;Running a storage node&quot;">​</a></h2><h3 id="arkel-storage" tabindex="-1"><code>arkel storage</code> <a class="header-anchor" href="#arkel-storage" aria-label="Permalink to &quot;`arkel storage`&quot;">​</a></h3><p>Boot up as a high-throughput raw block storage endpoint</p><p><strong>Usage:</strong> <code>arkel storage [OPTIONS]</code></p><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--private-relay-url &lt;PRIVATE_RELAY_URL&gt;</code> — Optional private Iroh relay architecture URL override</li><li><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs to register against (comma-separated; the registrar discovers the current Raft leader among them)</li><li><code>--addr &lt;ADDR&gt;</code> — Address the iroh QUIC endpoint binds to</li><li><code>--advertise-addr &lt;ADVERTISE_ADDR&gt;</code> — Address advertised for registration (defaults to --addr)</li><li><code>--gc-interval-secs &lt;GC_INTERVAL_SECS&gt;</code> — How often to scan and delete unreferenced shards (seconds)</li><li><code>--capacity &lt;CAPACITY&gt;</code> — Storage allocation this node commits to the network; the index fills it and pays against real stored bytes (default 1TB)</li></ul><h2 id="operating-the-network" tabindex="-1">Operating the network <a class="header-anchor" href="#operating-the-network" aria-label="Permalink to &quot;Operating the network&quot;">​</a></h2><h3 id="arkel-payment" tabindex="-1"><code>arkel payment</code> <a class="header-anchor" href="#arkel-payment" aria-label="Permalink to &quot;`arkel payment`&quot;">​</a></h3><p>Payment-operator tooling (register the quota credit key; first-wins)</p><p><strong>Usage:</strong> <code>arkel payment &lt;COMMAND&gt;</code></p><h6 id="subcommands-3" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-3" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>register</code> — Register this identity as the payment operator (one-time, first-wins)</li><li><code>credit</code> — Credit quota to an account (idempotent on --ref-id)</li><li><code>set-default-quota</code> — Set the cluster-wide default quota for accounts with no quota row yet (applies at first use; idempotent upsert, changeable)</li></ul><h3 id="arkel-payment-register" tabindex="-1"><code>arkel payment register</code> <a class="header-anchor" href="#arkel-payment-register" aria-label="Permalink to &quot;`arkel payment register`&quot;">​</a></h3><p>Register this identity as the payment operator (one-time, first-wins)</p><p><strong>Usage:</strong> <code>arkel payment register [OPTIONS]</code></p><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li></ul><h3 id="arkel-payment-credit" tabindex="-1"><code>arkel payment credit</code> <a class="header-anchor" href="#arkel-payment-credit" aria-label="Permalink to &quot;`arkel payment credit`&quot;">​</a></h3><p>Credit quota to an account (idempotent on --ref-id)</p><p><strong>Usage:</strong> <code>arkel payment credit [OPTIONS] --account &lt;ACCOUNT&gt; --bytes &lt;BYTES&gt; --ref-id &lt;REF_ID&gt;</code></p><h6 id="options-7" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-7" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--account &lt;ACCOUNT&gt;</code> — Account (hex iroh pubkey) to credit</p></li><li><p><code>--bytes &lt;BYTES&gt;</code> — Bytes of quota to add</p></li><li><p><code>--source &lt;SOURCE&gt;</code> — Credit source label (e.g. &#39;payment&#39;)</p><p>Default value: <code>payment</code></p></li><li><p><code>--ref-id &lt;REF_ID&gt;</code> — Idempotency reference (e.g. Stripe checkout id); replay is a no-op</p></li><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li></ul><h3 id="arkel-payment-set-default-quota" tabindex="-1"><code>arkel payment set-default-quota</code> <a class="header-anchor" href="#arkel-payment-set-default-quota" aria-label="Permalink to &quot;`arkel payment set-default-quota`&quot;">​</a></h3><p>Set the cluster-wide default quota for accounts with no quota row yet (applies at first use; idempotent upsert, changeable)</p><p><strong>Usage:</strong> <code>arkel payment set-default-quota [OPTIONS] --bytes &lt;BYTES&gt;</code></p><h6 id="options-8" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-8" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--bytes &lt;BYTES&gt;</code> — Default quota, e.g. &quot;1GB&quot; (same syntax as --capacity)</p></li><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li></ul><h3 id="arkel-repair" tabindex="-1"><code>arkel repair</code> <a class="header-anchor" href="#arkel-repair" aria-label="Permalink to &quot;`arkel repair`&quot;">​</a></h3><p>Heal objects below target k/m (standalone, idempotent; run by cron)</p><p><strong>Usage:</strong> <code>arkel repair [OPTIONS]</code></p><h6 id="options-9" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-9" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--index-addrs &lt;INDEX_ADDRS&gt;</code> — Index node HTTP URLs (comma-separated)</p><p>Default value: <code>http://127.0.0.1:8001,http://127.0.0.1:8002,http://127.0.0.1:8003</code></p></li><li><p><code>--register</code> — Register this identity as the repair operator (one-time), then exit</p></li><li><p><code>--k &lt;K&gt;</code> — Re-encode target data shards (default 8)</p><p>Default value: <code>8</code></p></li><li><p><code>--m &lt;M&gt;</code> — Re-encode target parity shards (default 6)</p><p>Default value: <code>6</code></p></li><li><p><code>--rate-limit &lt;RATE_LIMIT&gt;</code> — Max objects fixed per run (rate limit)</p><p>Default value: <code>600</code></p></li></ul>',81)])])}const g=t(l,[["render",d]]);export{h as __pageData,g as default};
